import heapq

def match(orders):
    trades = []
    order_data = {}  # id -> dict(side, price, qty, active, seq)
    buy_heap = []  # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)

    def clean_top(heap):
        while heap:
            top = heap[0]
            rid = top[-1]
            info = order_data.get(rid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return top
        return None

    def match_incoming(side, price, qty):
        # price: None means match any price (market order)
        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while qty > 0:
            top = clean_top(opp_heap)
            if top is None:
                break
            rid = top[-1]
            info = order_data[rid]
            resting_price = info['price']

            if price is not None:
                if side == 'buy':
                    if resting_price > price:
                        break
                else:
                    if resting_price < price:
                        break

            # pop it, we're going to match at least partially
            heapq.heappop(opp_heap)

            trade_qty = min(qty, info['qty'])
            if side == 'buy':
                buy_id = None  # will fill below
            # determine buy_id/sell_id
            if side == 'buy':
                incoming_is_buy = True
            else:
                incoming_is_buy = False

            if incoming_is_buy:
                b_id = "__incoming__"
                s_id = rid
            else:
                b_id = rid
                s_id = "__incoming__"

            trades.append([b_id, s_id, resting_price, trade_qty])

            info['qty'] -= trade_qty
            qty -= trade_qty

            if info['qty'] > 0:
                heapq.heappush(opp_heap, top)
            else:
                info['active'] = False

        return qty

    for seq, order in enumerate(orders):
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            info = order_data.get(oid)
            if info is not None:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        # register order_data placeholder for tracking during matching (needed for trades referencing incoming id)
        # We'll process matching first, using a temporary id marker "__incoming__" then fix up trades afterward.
        remaining_qty = match_incoming(side, price, qty)

        # fix up trades that reference "__incoming__" with actual oid
        for t in trades:
            if t[0] == "__incoming__":
                t[0] = oid
            if t[1] == "__incoming__":
                t[1] = oid

        if typ == 'limit' and remaining_qty > 0:
            order_data[oid] = {'side': side, 'price': price, 'qty': remaining_qty, 'active': True, 'seq': seq}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            # if limit order fully filled, or ioc/market: mark inactive if exists (not added)
            if typ == 'limit':
                order_data[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False, 'seq': seq}

    return trades

